function crushRuns(s: string, k: number): string {
  let changed = true;
  while (changed) {
    changed = false;
    let start = 0;
    for (let i = 1; i <= s.length; i++) {
      if (i === s.length || s[i] !== s[start]) start = i;
      else if (i - start + 1 === k) {
        s = s.slice(0, start) + s.slice(i + 1);
        changed = true;
        break;
      }
    }
  }
  return s;
}

