function crushRuns(s: string, k: number): string {
  const letters: string[] = [], counts: number[] = [];
  for (const ch of s) {
    const top = letters.length - 1;
    if (top >= 0 && letters[top] === ch) {
      if (++counts[top] === k) { letters.pop(); counts.pop(); }
    } else {
      letters.push(ch);
      counts.push(1);
    }
  }
  let out = "";
  for (let i = 0; i < letters.length; i++) out += letters[i].repeat(counts[i]);
  return out;
}

