class Solution:
    def crushRuns(self, s: str, k: int) -> str:
        stack = []  # [letter, count]
        for ch in s:
            if stack and stack[-1][0] == ch:
                stack[-1][1] += 1
                if stack[-1][1] == k:
                    stack.pop()
            else:
                stack.append([ch, 1])
        return "".join(ch * c for ch, c in stack)

